To return standard HTTP error status codes, raise `HTTPException` from `fastapi`:

```python
from fastapi import FastAPI, HTTPException, Request, status
from fastapi.responses import JSONResponse

app = FastAPI()

# 1. Standard HTTPException
@app.get("/items/{item_id}")
async def get_item(item_id: int):
    if item_id == 0:
        raise HTTPException(
            status_code=status.HTTP_404_NOT_FOUND,
            detail=f"Item {item_id} not found",
            headers={"X-Error-Code": "ITEM_NOT_FOUND"}
        )
    return {"item_id": item_id, "title": "Laptop"}

# 2. Custom Domain Exception Handler
class BusinessLogicError(Exception):
    def __init__(self, message: str):
        self.message = message

@app.exception_handler(BusinessLogicError)
async def business_error_handler(request: Request, exc: BusinessLogicError):
    return JSONResponse(
        status_code=400,
        content={"error": "Business Rule Violation", "detail": exc.message}
    )
```

FastAPI includes `TestClient` (built on `httpx`), allowing you to test endpoints synchronously without running a live network port:

```python
from fastapi import FastAPI
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/health")
def health():
    return {"status": "ok", "code": 200}

# Test suite
client = TestClient(app)

def test_health_endpoint():
    response = client.get("/health")
    assert response.status_code == 200
    assert response.json() == {"status": "ok", "code": 200}

def test_not_found():
    response = client.get("/non-existent-route")
    assert response.status_code == 404
```

Flask is a lightweight WSGI micro web framework. Here is how to create a basic application:

```python
from flask import Flask, jsonify

app = Flask(__name__)

# Basic route
@app.route("/")
def home():
    return "Welcome to the Flask Web Service!"

# Dynamic URL parameter with type converter (int)
@app.route("/user/<int:user_id>")
def get_user(user_id):
    return jsonify({"user_id": user_id, "role": "developer"})

if __name__ == "__main__":
    app.run(debug=True, port=5000)
```

Flask provides the global proxy object `request` for inspecting incoming HTTP data:

```python
from flask import Flask, request, jsonify

app = Flask(__name__)

# 1. Handling GET Query Parameters (?search=keyword&page=1)
@app.route("/search", methods=["GET"])
def search():
    term = request.args.get("search", default="", type=str)
    page = request.args.get("page", default=1, type=int)
    return jsonify({"term": term, "page": page})

# 2. Handling POST JSON Body
@app.route("/api/orders", methods=["POST"])
def create_order():
    payload = request.get_json(silent=True)
    if not payload or "item" not in payload:
        return jsonify({"error": "Invalid JSON or missing item"}), 400

    return jsonify({"status": "Order created", "data": payload}), 201
```

Flask integrates with the Jinja2 template engine via `render_template()`:

```python
from flask import Flask, render_template

app = Flask(__name__)

@app.route("/dashboard")
def dashboard():
    user_info = {"name": "Alice", "role": "Admin"}
    recent_tasks = ["Review PR #42", "Deploy v1.2", "Verify Backups"]
    return render_template("dashboard.html", user=user_info, tasks=recent_tasks)
```

### Sample `templates/dashboard.html`
```html
<h1>Welcome, {{ user.name }} ({{ user.role }})</h1>
<ul>
  {% for task in tasks %}
    <li>{{ task }}</li>
  {% endfor %}
</ul>
```

Custom error handlers intercept HTTP exceptions and return standardized error pages or JSON responses:

```python
from flask import Flask, jsonify

app = Flask(__name__)

@app.errorhandler(404)
def not_found_error(error):
    return jsonify({
        "status": 404,
        "error": "Not Found",
        "message": "The requested URL was not found on this server."
    }), 404

@app.errorhandler(500)
def internal_error(error):
    return jsonify({
        "status": 500,
        "error": "Internal Server Error",
        "message": "An unexpected error occurred."
    }), 500
```

Flask's `session` object uses cryptographically signed browser cookies to store state across requests without server-side storage:

```python
from flask import Flask, session, redirect, url_for

app = Flask(__name__)
app.secret_key = "super-secure-secret-key"  # Required for signing sessions

@app.route("/login/<username>")
def login(username):
    session["user"] = username
    session["logged_in"] = True
    return f"Logged in as {username}"

@app.route("/profile")
def profile():
    if not session.get("logged_in"):
        return redirect(url_for("login", username="guest"))
    return f"Current profile user: {session['user']}"

@app.route("/logout")
def logout():
    session.clear()
    return "Logged out"
```

`g` is a namespace object stored inside the application context that lasts for the duration of a **single request**:

```python
from flask import Flask, g

app = Flask(__name__)

def get_db():
    # Initialize db connection once per request on 'g'
    if "db" not in g:
        g.db = {"connection": "sqlite3_active_handle"}
    return g.db

@app.route("/data")
def fetch_data():
    db = get_db()
    return {"status": "Query executed", "db": db["connection"]}
```

Unlike `session` (which is stored on client cookies), `g` is purely server-side memory for sharing objects between views and middleware.

Flask provides `abort()` to immediately halt execution with an HTTP status code, and `redirect()` combined with `url_for()` for dynamic redirection:

```python
from flask import Flask, abort, redirect, url_for

app = Flask(__name__)

@app.route("/admin")
def admin():
    is_admin = False
    if not is_admin:
        abort(403)  # Immediately raises HTTP 403 Forbidden
    return "Welcome Admin"

@app.route("/old-home")
def old_home():
    # Safely redirects to the view function named 'new_home'
    return redirect(url_for("new_home"), code=301)

@app.route("/new-home")
def new_home():
    return "Welcome to the new home page!"
```
